/bin/bash -c "python3 - <<'PY'
import cv2, numpy as np
im=cv2.imread('first_frame.png'); gray=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
# crop/edge lines region
for name,(x0,y0,x1,y1) in {'left':(0,50,650,380),'mid':(600,100,1100,430),'right':(1000,150,1280,450)}.items():
 c=gray[y0:y1,x0:x1]; e=cv2.Canny(c,20,60)
 lines=cv2.HoughLinesP(e,1,np.pi/180,threshold=20,minLineLength=25,maxLineGap=8)
 print('\\n',name)
 if lines is not None:
  arr=[]
  for l in lines:
   xa,ya,xb,yb=l[0]; xa+=x0;xb+=x0;ya+=y0;yb+=y0
   length=np.hypot(xb-xa,yb-ya);ang=np.degrees(np.arctan2(yb-ya,xb-xa))
   if length>35: arr.append((length,ang,(xa,ya,xb,yb)))
  for L,a,l in sorted(arr,reverse=True)[:40]: print(round(L,1),round(a,1),l)
PY"
